function mcSvg(){let seed=7;const rnd=()=>(seed=(seed*9301+49297)%233280)/233280;const W=34,H=19.5,Dp=38,ox=210,oy=95;const G=["#86d94a","#5fa634","#487f27"],Dt=["#a0714a","#7d5535","#61422a"],St=["#a7a7ae","#808088","#62626a"],Dm=["#67f0dd","#2dd4bf","#119c8c"],Go=["#fde047","#d4a90f","#a38306"];
 const cells=[[0,0,0,G],[1,0,0,G],[2,0,0,G],[3,0,0,G],[0,0,1,G],[1,0,1,Dt],[2,0,1,St],[3,0,1,G],[0,0,2,G],[1,0,2,G],[2,0,2,G],[3,0,2,Dt],[0,0,3,G],[1,0,3,G],[2,0,3,G],[3,0,3,G],[1,1,1,G],[2,1,1,Dm],[2,1,2,G],[1,1,2,Go],[2,2,1,G]].sort((a,b)=>a[1]-b[1]||a[0]+a[2]-b[0]-b[2]);let o="";
 for(const[x,y,z,c]of cells){const px=ox+(x-z)*W,py=oy+(x+z)*H-y*Dp;o+=`<g stroke="rgba(0,0,0,.35)"><polygon points="${px-W},${py} ${px},${py+H} ${px},${py+H+Dp} ${px-W},${py+Dp}" fill="${c[1]}"/><polygon points="${px+W},${py} ${px},${py+H} ${px},${py+H+Dp} ${px+W},${py+Dp}" fill="${c[2]}"/><polygon points="${px},${py-H} ${px+W},${py} ${px},${py+H} ${px-W},${py}" fill="${c[0]}"/></g>`}
 return`<svg viewBox="0 0 420 300" class="fl">${o}</svg>`}
