function lightning(n=3,H=520){let o="";const xs=[14,38,62,86,50];for(let i=0;i<n+2;i++){const x=xs[i%5];o+=`<i class="beam" style="left:${x}%;--r:${(x-50)/5}deg;--d:${7+i*1.3}s;animation-delay:${-i*1.7}s;width:${150+i%3*70}px"></i>`}
 o+=`<i class="spot" style="left:12%;top:-80px"></i><i class="spot" style="right:8%;top:-60px;--c:var(--acc2rgb)"></i><i class="spot lo" style="left:42%;bottom:-120px"></i>`;
 return`<div class="lt">${o}</div>`}
function hills(seed,base,amp,color,top,bs=28,W=1680,H=520){let o="";const n=Math.ceil(W/bs);for(let i=0;i<n;i++){const v=Math.sin(i*.11+seed)*.5+Math.sin(i*.043+seed*2.3)*.8+Math.sin(i*.27+seed*.7)*.25,h=Math.round((base+amp*v)/bs)*bs,y=H-h;o+=`<rect x="${i*bs}" y="${y}" width="${bs}" height="${h}" fill="${color}"/><rect x="${i*bs}" y="${y}" width="${bs}" height="${bs*.45}" fill="${top}"/>`}return`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMax slice" width="100%" height="100%">${o}</svg>`}
function cloud(x,y,s,d,o){const b=[[0,1,3],[1,0,2],[3,1,2],[2,0,1]].map(r=>`<rect x="${r[0]*s}" y="${r[1]*s*.55}" width="${r[2]*s}" height="${s*.6}" fill="#fff"/>`).join("");return`<svg style="position:absolute;left:${x}%;top:${y}px;opacity:${o};animation:cl ${d}s linear infinite" width="${s*5}" height="${s*1.4}" viewBox="0 0 ${s*5} ${s*1.4}">${b}</svg>`}
function miniCube(c,sz=46){const w=sz,h=sz*.58,d=sz*.9;return`<svg width="${w*2+4}" height="${h*2+d+4}" viewBox="${-w-2} ${-h-2} ${w*2+4} ${h*2+d+4}"><g stroke="rgba(0,0,0,.35)"><polygon points="${-w},0 0,${h} 0,${h+d} ${-w},${d}" fill="${c[1]}"/><polygon points="${w},0 0,${h} 0,${h+d} ${w},${d}" fill="${c[2]}"/><polygon points="0,${-h} ${w},0 0,${h} ${-w},0" fill="${c[0]}"/></g></svg>`}
