function gauge(g){const r=34,C=2*Math.PI*r;return`<div class="card h rv tc gz"><svg viewBox="0 0 90 90" width="104" height="104"><circle cx="45" cy="45" r="${r}" fill="none" stroke="var(--s2)" stroke-width="8"/><circle class="gc" cx="45" cy="45" r="${r}" fill="none" stroke="url(#gg)" stroke-width="8" stroke-linecap="round" stroke-dasharray="${C*g[3]/100} ${C}" transform="rotate(-90 45 45)" style="--len:${C*g[3]/100};--C:${C}"/><text x="45" y="50" text-anchor="middle" fill="var(--fg)" font-size="17" font-weight="800">${g[1]}</text></svg><b style="font-size:20px;display:block;margin-top:6px">${g[4]}</b><small class="mut">${g[0]} · ${g[2]}</small></div>`}
function freePage(k){const F=FREE[k],o="Free "+F.short;return{nav:"free-"+k,html:()=>`
<div class="freewrap ${F.cls}"><section class="fhero">${BG[k]()}<div class="wrap hero" style="position:relative;z-index:2"><div><div class="pill rv"><i class="dot"></i>🎁 100% FREE · No credit card</div><h1 class="rv">${F.h}</h1><p class="sub rv">${F.sub}</p><div class="row g12 wr rv"><a class="btn p lg" href="#claim">Claim ${o} →</a><a class="btn lg" href="#compare" style="backdrop-filter:blur(8px)">Free vs Paid</a></div><div class="rv" style="margin-top:28px;max-width:430px"><div class="row sp" style="font-size:13px;margin-bottom:7px"><span class="mut">🔥 Free ${F.slots[1]} claimed today</span><b>${F.slots[0]}%</b></div><div class="bar" style="height:9px"><i style="width:${F.slots[0]}%"></i></div><small class="dim" style="font-size:11.5px">Demo counter — connect to your real stock</small></div></div>
<div class="glass rv fcard" style="padding:26px;position:relative;overflow:hidden"><div class="ribbon">FREE</div><div class="row g12" style="margin-bottom:18px"><div class="fic">${F.icon}</div><div><b style="font-size:20px">${F.title}</b><br><small class="mut">${F.badge}</small></div></div><div class="termx" id="tx"></div><div class="row sp" style="margin-top:20px;align-items:flex-end"><div><div class="pr">₹0<small> /forever</small></div></div><a class="btn p lg" href="#claim">Claim now →</a></div></div></div></section>
${MQ(F.soft.map(s=>s[0]))}
<section class="wrap sec">${SH("Your free specs","Serious power. <em>Zero cost.</em>")}<svg width="0" height="0"><defs><linearGradient id="gg" x1="0" x2="1"><stop offset="0" stop-color="var(--acc)"/><stop offset="1" stop-color="var(--acc2)"/></linearGradient></defs></svg><div class="grid4">${F.gauges.map(gauge).join("")}</div></section>
<section class="wrap sec">${SH("What you can do","Build <em>anything.</em>")}<div class="grid3">${F.uses.map(u=>`<div class="card h fe rv"><div class="ic">${u[0]}</div><h3>${u[1]}</h3><p>${u[2]}</p></div>`).join("")}</div></section>
<section class="wrap sec">${SH("Software",F.softT.replace(/^Choose/,"Pick")+" <em>— your way.</em>")}<div class="soft rv">${F.soft.map((s,i)=>`<div class="sf ${i?"":"on"}"><span style="background:${s[2]}22;color:${s[2]};border:1px solid ${s[2]}66">${s[1]}</span><b>${s[0]}</b></div>`).join("")}</div></section>
<section class="wrap sec">${SH("Included","Everything you get — <em>free.</em>")}<div class="grid4">${F.inc.map(x=>`<div class="card h rv row g12" style="padding:18px"><span style="width:32px;height:32px;border-radius:10px;display:grid;place-items:center;background:color-mix(in srgb,var(--acc) 18%,transparent);color:var(--acc);font-weight:800;flex:none">✓</span><b style="font-size:14px;line-height:1.35">${x}</b></div>`).join("")}</div></section>
<section class="wrap sec">${SH("How it works","Claim in <em>3 easy steps.</em>")}<div class="tl rv">${[["1","Join Discord & sign up","Create your account and join the community server."],["2","Verify & claim","Verify your email and press Claim — no payment needed."],["3","Deploy & play","Ready in about a minute. Renew every 7 days to keep it."]].map(s=>`<div class="ts"><span>${s[0]}</span><h3>${s[1]}</h3><p class="mut">${s[2]}</p></div>`).join("")}</div></section>
<section class="wrap sec" id="compare">${SH("Free vs Paid","Start free. <em>Scale when ready.</em>")}<div class="tw rv" style="max-width:860px;margin:0 auto"><table class="t"><thead><tr><th></th><th>🎁 Free</th><th style="color:var(--acc)">Paid plans</th></tr></thead><tbody>${F.lim.map(r=>`<tr><td class="mut">${r[0]}</td><td>${r[1]}</td><td style="color:var(--acc);font-weight:700">${r[2]}</td></tr>`).join("")}</tbody></table></div><div class="tc rv" style="margin-top:22px"><a class="btn lg" href="${F.up[1]}">${F.up[2]} →</a></div></section>
<section class="wrap sec" id="claim">${SH("Claim yours","Get your <em>"+o.toLowerCase()+"</em> now.")}<div class="grid2" style="max-width:980px;margin:0 auto"><div class="col g16 rv"><div class="card col g12"><h3>Eligibility checklist</h3>${F.req.map(r=>`<label class="row g12" style="cursor:pointer"><input type="checkbox" checked style="accent-color:var(--acc);width:18px;height:18px"><span>${r}</span></label>`).join("")}<div class="bd ok" style="align-self:flex-start">You're eligible</div></div><div class="card"><small class="dim" style="letter-spacing:.12em;text-transform:uppercase;font-weight:700">Live preview</small><div class="row g12" style="margin-top:12px"><div class="fic">${F.icon}</div><div><b id="pv1">${k==="vps"?"my-vps":"myworld.axionhost.net"}</b><br><small class="mut" id="pv2">${k==="vps"?"Ubuntu 24.04 · 8 GB RAM":"Paper · 4 GB RAM · 20 slots"}</small></div><span class="bd ok" style="margin-left:auto">Ready</span></div></div></div>
<form class="card col g16 rv" id="cf"><h3>Claim form</h3><label class="f">Email<input class="in" type="email" required placeholder="you@email.com"></label><label class="f">Discord username<input class="in" required placeholder="username"></label><label class="f">${k==="vps"?"Operating system":"Server software"}<select class="in" id="cs">${F.soft.map(s=>`<option>${s[0]}</option>`).join("")}</select></label><label class="f">${k==="vps"?"Hostname":"Subdomain"}<div class="row g8"><input class="in" id="ch" required placeholder="${k==="vps"?"my-vps":"myworld"}">${k==="vps"?"":'<span class="mut">.axionhost.net</span>'}</div></label><label class="row g12" style="color:var(--mut);font-size:13.5px"><input type="checkbox" required style="accent-color:var(--acc)"> I agree to the Free Plan Terms (fair use, 7-day renewal)</label><button class="btn p lg">Claim ${o} →</button></form></div></section>
<section class="wrap sec" id="faq">${SH("FAQ","Free plan <em>questions.</em>")}<div class="faq rv">${F.faq.map((f,i)=>`<details ${i?"":"open"}><summary>${f[0]}</summary><div>${f[1]}</div></details>`).join("")}</div></section>
<section class="wrap"><div class="cta2 rv fcta"><h2>Outgrowing free?</h2><p>Paid plans start at just ₹${F.from}/month with backups, priority support and way more power.</p><div class="row g12 wr" style="justify-content:center"><a class="btn p lg" href="${F.up[1]}">${F.up[2]} →</a><a class="btn lg" href="pricing.html">All plans</a></div></div></section></div>`,
 mount(){document.body.classList.add(F.cls);const T=$("#tx");let i=0,j=0,h="";const e=s=>s.replace(/&/g,"&amp;").replace(/</g,"&lt;");const L=F.term;(function st(){if(i>=L.length){T.innerHTML=h+'<span class="cur"></span>';setTimeout(()=>{i=j=0;h="";st()},4200);return}const[c,t]=L[i];j++;T.innerHTML=h+`<div class="${c}">${e(t.slice(0,j))}<span class="cur"></span></div>`;if(j>=t.length){h+=`<div class="${c}">${e(t)}</div>`;i++;j=0;setTimeout(st,c==="c"?320:140)}else setTimeout(st,c==="c"?24:6)})();
  $$(".sf").forEach(x=>x.onclick=()=>{$$(".sf").forEach(y=>y.classList.toggle("on",y===x));const s=F.soft.find(q=>q[0]===$("b",x).textContent);$("#cs").value=s[0]});
  const up=()=>{const v=$("#ch").value.trim()||(k==="vps"?"my-vps":"myworld");$("#pv1").textContent=k==="vps"?v:v+".axionhost.net";$("#pv2").textContent=(k==="vps"?$("#cs").value+" · 8 GB RAM":$("#cs").value+" · 4 GB RAM · 20 slots")};$("#ch").oninput=up;$("#cs").onchange=up;
  $("#cf").onsubmit=async ev=>{ev.preventDefault();if(await Net.probe()){if(!Net.token()){toast("Log in (and verify your email) to claim","var(--warn)");setTimeout(()=>location.href="login.html?next=free-"+F.k+".html",700);return}const r=await Net.post("/free/claim",{type:F.k});if(!r.ok){toast(r.data.error||"Could not claim","var(--bad)");return}return modal(`<div class="tc"><div style="width:68px;height:68px;border-radius:50%;background:linear-gradient(135deg,var(--acc),var(--acc2));display:grid;place-items:center;font-size:32px;color:#04120a;margin:0 auto 14px;font-weight:800">✓</div><h3 style="font-size:24px">${r.data.provisioned?"It's live!":"Request received!"}</h3><p class="mut" style="margin:8px 0 18px">${r.data.provisioned?"Your server is ready — login details were emailed to you.":r.data.note}</p><a class="btn p" href="${F.k==='vps'?'vps-panel.html':'mc-panel.html'}">Open my panel →</a></div>`)}modal(`<div class="tc"><div style="width:68px;height:68px;border-radius:50%;background:linear-gradient(135deg,var(--acc),var(--acc2));display:grid;place-items:center;font-size:32px;color:#04120a;margin:0 auto 14px;font-weight:800">✓</div><h3 style="font-size:24px">Request received!</h3><p class="mut" style="margin:8px 0 18px">We are setting up your ${o.toLowerCase()}. Details will arrive by email and Discord DM shortly.</p><a class="btn p" href="${F.k==='vps'?'vps-panel.html':'mc-panel.html'}">Open my panel →</a></div>`)};
  const fh=$(".fhero");fh.addEventListener("mousemove",ev=>{const r=fh.getBoundingClientRect(),x=(ev.clientX-r.left)/r.width-.5;$$(".lay",fh).forEach(l=>l.style.transform=`translateX(${-x*l.dataset.d}px)`)})}}}

const rnd=(n,f)=>Array.from({length:n},(_,i)=>f(i)).join("");
Object.assign(BG,{
 rust:()=>`<div class="fbg rsbg"><div class="sky"></div><div class="moon"></div><div class="glow"></div><div class="lay" data-d="20" style="bottom:60px;opacity:.9">${hills(2.2,190,80,"#1c0a05","#3a1408")}</div><div class="lay" data-d="34" style="bottom:0">${hills(5.5,140,55,"#0e0503","#7c2d12")}</div><div class="emb">${rnd(30,i=>`<i style="left:${(i*37)%100}%;animation-delay:${-(i*.6)}s;animation-duration:${5+(i%5)}s"></i>`)}</div>${lightning(3,520)}<div class="vig"></div></div>`,
 bots:()=>`<div class="fbg vpbg"><div class="aur"></div><div class="floor"></div>${[["await bot.start()",8,"22%"],["✓ online · 24/7",74,"18%"],["git pull origin main",64,"68%"],["pm2 restart bot",10,"70%"]].map((b,i)=>`<div class="fbub" style="left:${b[1]}%;top:${b[2]};animation-delay:${-i*1.3}s">${b[0]}</div>`).join("")}${lightning(3,520)}<div class="vig"></div></div>`,
 home:()=>`<div class="fbg vpbg electric"><div class="aur"></div><div class="floor"></div><div class="rain">${rnd(18,i=>`<i style="left:${(i*5.7+2)%100}%;animation-delay:${-(i*.9)}s;animation-duration:${3+(i%4)}s;height:${60+(i%5)*30}px"></i>`)}</div>${[["⛏",4,"18%"],["🖥",46,"10%"],["🤖",52,"78%"],["🔥",3,"72%"]].map((b,i)=>`<div class="ficon" style="left:${b[1]}%;top:${b[2]};animation-delay:${-i*1.2}s">${b[0]}</div>`).join("")}${lightning(4,520)}<div class="vig"></div></div>`,
 gen:()=>`<div class="fbg vpbg electric"><div class="aur"></div><div class="floor"></div>${lightning(3,420)}<div class="vig"></div></div>`
});
